4. //!
5. //! # Fixed-Size Bump Allocator
6. //!
7. //! A generic, `no_std`-compatible bump allocator that hands out fixed-size slots from a
8. //! statically reserved memory region (typically BSS). Each slot is allocated exactly once via an
9. //! atomic compare-and-swap index, making the allocator lock-free and safe for concurrent use.
10. //!
11. //! ## Key Types
12. //!
13. //! - [`BssStorage`] — unsafe trait implemented by the backing store provider.
14. //! - [`FixedSizeBumpAllocator`] — the allocator parameterised by unit size, alignment, and
15. //!   storage backend.
16. //! - [`BumpAllocError`] — error type returned when allocation fails.
17. //!
18. //! ## Usage
19. //!
20. //! 1. Define a static storage region and implement [`BssStorage`] for it.
21. //! 2. Create a `static` [`FixedSizeBumpAllocator`] with [`FixedSizeBumpAllocator::new()`].
22. //! 3. Call [`alloc()`](FixedSizeBumpAllocator::alloc) to obtain raw byte slots, or
23. //!    [`alloc_as()`](FixedSizeBumpAllocator::alloc_as) for typed `MaybeUninit<T>` slots.
24. //!
25. //! ## Example
26. //!
27. //! ```rust
28. //! use bump_allocator::{align_up, BssStorage, BumpAllocError, FixedSizeBumpAllocator};
29. //!
30. //! const UNIT_SIZE: usize = 64;
31. //! const UNIT_ALIGN: usize = 64;
32. //! const NUM_SLOTS: usize = 4;
33. //! const STRIDE: usize = match align_up(UNIT_SIZE, UNIT_ALIGN) {
34. //!     Some(v) => v,
35. //!     None => panic!("stride overflow"),
36. //! };
37. //! const STORAGE_SIZE: usize = NUM_SLOTS * STRIDE;
38. //!
39. //! #[repr(align(64))]
40. //! struct MyStorage {
41. //!     bytes: [u8; STORAGE_SIZE],
42. //! }
43. //!
44. //! static mut BACKING: MyStorage = MyStorage {
45. //!     bytes: [0; STORAGE_SIZE],
46. //! };
47. //!
48. //! struct MyBackend;
49. //!
50. //! // SAFETY: BACKING is a stable, properly aligned static region exclusively managed by
51. //! // the allocator.
52. //! unsafe impl BssStorage for MyBackend {
53. //!     const NUM_UNITS: usize = NUM_SLOTS;
54. //!     const STORAGE_SIZE: usize = STORAGE_SIZE;
55. //!
56. //!     fn as_mut_ptr() -> *mut u8 {
57. //!         unsafe { core::ptr::addr_of_mut!(BACKING.bytes) as *mut u8 }
58. //!     }
59. //! }
60. //!
61. //! // SAFETY: single allocator instance for `MyBackend`.
62. //! static ALLOCATOR: FixedSizeBumpAllocator<UNIT_SIZE, UNIT_ALIGN, MyBackend> =
63. //!     unsafe { FixedSizeBumpAllocator::new() };
64. //!
65. //! // Allocate raw byte slots.
66. //! let slot_a: &mut [u8; UNIT_SIZE] = ALLOCATOR.alloc().expect("slot a");
67. //! let slot_b: &mut [u8; UNIT_SIZE] = ALLOCATOR.alloc().expect("slot b");
68. //! assert_ne!(slot_a.as_ptr(), slot_b.as_ptr());
69. //!
70. //! // Allocate a typed slot (caller must initialise before reading).
71. //! let uninit: &mut core::mem::MaybeUninit<[u32; 16]> =
72. //!     unsafe { ALLOCATOR.alloc_as::<[u32; 16]>().expect("typed slot") };
73. //! uninit.write([0u32; 16]);
74. //! let typed: &mut [u32; 16] = unsafe { uninit.assume_init_mut() };
75. //! typed[0] = 42;
76. //! assert_eq!(typed[0], 42);
77. //! ```
78. 
79. //==================================================================================================
80. // Configuration
81. //==================================================================================================
82. 
83. #![cfg_attr(not(any(test, feature = "std")), no_std)]
84. 
85. //==================================================================================================
86. // Imports
87. //==================================================================================================
88. 
89. use ::core::{
90.     fmt,
91.     marker::PhantomData,
92.     mem::MaybeUninit,
93.     sync::atomic::{
94.         AtomicUsize,
95.         Ordering,
96.     },
97. };
98. use ::vstd::prelude::*;
99. 
100. // Include specifications.
101. #[cfg(verus_keep_ghost)]
102. include!("lib.spec.rs");
103. 
104. // Include proofs.
105. #[cfg(verus_keep_ghost)]
106. include!("lib.proof.rs");
