108. //==================================================================================================
109. // Traits and Types
110. //==================================================================================================
111. 
112. ///
113. /// # Description
114. ///
115. /// Aligns `value` up to the next multiple of `alignment`.
116. ///
117. /// # Parameters
118. ///
119. /// - `value`: Value to align.
120. /// - `alignment`: Alignment boundary.
121. ///
122. /// # Returns
123. ///
124. /// Returns the aligned value, or `None` if `alignment` is zero or the computation overflows.
125. ///
126. #[verus_spec(result =>
127.     ensures
128.         match result {
129.             Some(r) => align_up_spec(value as nat, alignment as nat) == Some(r as nat),
130.             None => align_up_spec(value as nat, alignment as nat) is None,
131.         },
132. )]
133. pub const fn align_up(value: usize, alignment: usize) -> Option<usize> {
134.     if alignment == 0 {
135.         return None;
136.     }
137.     // VERUS DEVIATION: the original body was
138.     //   `value.div_ceil(alignment).checked_mul(alignment)`.
139.     // Verus ships no specification for the `usize::div_ceil` intrinsic (confirmed:
140.     // not present in vstd `std_specs`), and the only ways to give it meaning are
141.     // `assume_specification`/`external_body`, both of which are unapproved cheating
142.     // for this function. The ceiling division is therefore open-coded into the
143.     // arithmetically-equivalent `value / alignment` (+1 on a non-zero remainder).
144.     // This preserves semantics and O(1) time/space. `qd + 1` cannot overflow
145.     // because a non-zero remainder forces `alignment >= 2`, hence
146.     // `qd <= value / 2 < usize::MAX` (see `lemma_ceil_div`).
147.     let r: usize = value % alignment;
148.     let qd: usize = value / alignment;
149.     proof! {
150.         vstd::arithmetic::div_mod::lemma_fundamental_div_mod(value as int, alignment as int);
151.         if r != 0 {
152.             assert(alignment >= 2);
153.             assert((alignment as int) * (qd as int) <= value as int);
154.             assert(2 * (qd as int) <= (alignment as int) * (qd as int)) by (nonlinear_arith)
155.                 requires
156.                     alignment >= 2,
157.                     qd >= 0,
158.             ;
159.             assert(qd < usize::MAX);
160.         }
161.     }
162.     let q: usize = if r == 0 { qd } else { qd + 1 };
163.     proof! {
164.         lemma_ceil_div(value as int, alignment as int, qd as int, r as int);
165.     }
166.     q.checked_mul(alignment)
167. }
168. 
169. ///
170. /// # Description
171. ///
172. /// Error type returned by [`FixedSizeBumpAllocator`] operations.
173. ///
174. #[derive(Debug, Clone, Copy, PartialEq, Eq)]
175. #[verus_verify]
176. pub enum BumpAllocError {
177.     /// Storage capacity exhausted.
178.     Exhausted,
179.     /// Type size does not match allocator unit size.
180.     SizeMismatch,
181.     /// Type alignment exceeds allocator alignment.
182.     AlignmentMismatch,
183.     /// Internal arithmetic overflow.
184.     Overflow,
185.     /// Computed slot exceeds storage bounds.
186.     OutOfBounds,
187.     /// Computed slot is not properly aligned.
188.     Misaligned,
189. }
190. 
191. impl fmt::Display for BumpAllocError {
192.     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
193.         match self {
194.             Self::Exhausted => write!(f, "fixed-size BSS allocator exhausted"),
195.             Self::SizeMismatch => write!(f, "type size does not match allocator unit size"),
196.             Self::AlignmentMismatch => write!(f, "type alignment exceeds allocator alignment"),
197.             Self::Overflow => write!(f, "allocator internal arithmetic overflow"),
198.             Self::OutOfBounds => write!(f, "allocator slot exceeds storage bounds"),
199.             Self::Misaligned => write!(f, "allocator returned misaligned slot"),
200.         }
201.     }
202. }
203. 
204. ///
205. /// # Description
206. ///
207. /// Backend trait for fixed-size allocators that draw memory from static storage.
208. ///
209. /// # Safety
210. ///
211. /// Implementers must guarantee that:
212. ///
213. /// - `as_mut_ptr()` returns a stable pointer to a backing region of at least `STORAGE_SIZE`
214. ///   bytes for the allocator lifetime.
215. /// - the backing region is writable and properly aligned for any allocation site that uses this
216. ///   backend.
217. /// - the backing region is exclusively managed by this allocator API, so creating `&'static mut`
218. ///   references from slots cannot alias with other mutable references.
219. ///
220. #[verus_verify]
221. pub unsafe trait BssStorage {
222.     /// Number of fixed-size units that can be allocated.
223.     const NUM_UNITS: usize;
224. 
225.     /// Total size in bytes of the backing storage region.
226.     const STORAGE_SIZE: usize;
227. 
228.     /// Returns a mutable pointer to the beginning of the storage region.
229.     #[verus_spec(result =>
230.         ensures
231.             result as int == base_of::<Self>(),
232.     )]
233.     fn as_mut_ptr() -> *mut u8;
234. }
235. 
236. ///
237. /// # Description
238. ///
239. /// Generic fixed-size bump allocator over statically reserved memory.
240. ///
241. /// # Type Parameters
242. ///
243. /// - `N`: Unit size in bytes.
244. /// - `A`: Unit alignment in bytes.
245. /// - `S`: Backing storage provider.
246. ///
247. #[verus_verify]
248. pub struct FixedSizeBumpAllocator<const N: usize, const A: usize, S: BssStorage> {
249.     /// Atomic bump index for the next available slot.
250.     next_slot: AtomicUsize,
251.     /// Marker for the backend storage provider.
252.     _storage: PhantomData<S>,
253. }
254. 
255. impl<const N: usize, const A: usize, S: BssStorage> FixedSizeBumpAllocator<N, A, S> {
256.     ///
257.     /// # Description
258.     ///
259.     /// Creates a new fixed-size bump allocator.
260.     ///
261.     /// # Returns
262.     ///
263.     /// Returns a new allocator.
264.     ///
265.     /// # Safety
266.     ///
267.     /// The caller must ensure that only **one** `FixedSizeBumpAllocator` instance exists for a
268.     /// given `S: BssStorage` backend at any time. Creating multiple allocators over the same
269.     /// backend causes independent bump counters, which leads to overlapping slot reservations
270.     /// and undefined behavior (multiple `&'static mut` references to the same memory).
271.     ///
272.     pub const unsafe fn new() -> Self {
273.         Self {
274.             next_slot: AtomicUsize::new(0),
275.             _storage: PhantomData,
276.         }
277.     }
278. 
279.     ///
280.     /// # Description
281.     ///
282.     /// Allocates the next fixed-size slot as a raw byte array.
283.     ///
284.     /// # Returns
285.     ///
286.     /// On success, returns a mutable reference to a unit-sized byte array.
287.     ///
288.     /// # Errors
289.     ///
290.     /// - [`BumpAllocError::Exhausted`] if storage capacity is exhausted.
291.     /// - [`BumpAllocError::Overflow`] if internal arithmetic overflows.
292.     /// - [`BumpAllocError::OutOfBounds`] if computed slot exceeds storage bounds.
293.     /// - [`BumpAllocError::Misaligned`] if computed slot is not properly aligned.
294.     ///
295.     // SAFETY-SPEC: `external_body` because the success path materializes a
296.     // `&'static mut [u8; N]` from a backend-provided address (`usize as *mut`), a
297.     // raw-memory operation Verus cannot verify without a `PointsTo` permission for
298.     // the externally-owned `BssStorage` region. Mirrors the `src/libs/raw-array`
299.     // pattern. Registered in `verus-ai-logs/tcb-allowed.md`.
300.     #[verus_verify(external_body)]
301.     #[verus_spec(result =>
302.         requires bump_view(self).inv(),
303.         ensures
304.             match result {
305.                 Ok(slot) => {
306.                     let v = bump_view(self);
307.                     let a = slot_ref_addr(slot);
308.                     &&& a % (v.unit_align as int) == 0
309.                     &&& v.base <= a
310.                     &&& a + (N as int) <= v.base + (v.storage_size as int)
311.                 },
312.                 Err(e) => e == BumpAllocError::Exhausted,
313.             },
314.     )]
315.     pub fn alloc(&self) -> Result<&'static mut [u8; N], BumpAllocError> {
316.         // Reserve a slot index via compare-and-swap to avoid overshooting the counter.
317.         let idx: usize = loop {
318.             let current: usize = self.next_slot.load(Ordering::Acquire);
319.             if current >= S::NUM_UNITS {
320.                 return Err(BumpAllocError::Exhausted);
321.             }
322.             let next: usize = current.checked_add(1).ok_or(BumpAllocError::Overflow)?;
323.             if self
324.                 .next_slot
325.                 .compare_exchange(current, next, Ordering::AcqRel, Ordering::Acquire)
326.                 .is_ok()
327.             {
328.                 break current;
329.             }
330.         };
331. 
332.         let stride: usize = align_up(N, A).ok_or(BumpAllocError::Overflow)?;
333.         let offset: usize = idx.checked_mul(stride).ok_or(BumpAllocError::Overflow)?;
334. 
335.         let base: usize = S::as_mut_ptr() as usize;
336.         let ptr: usize = base.checked_add(offset).ok_or(BumpAllocError::Overflow)?;
337.         let end: usize = ptr.checked_add(N).ok_or(BumpAllocError::Overflow)?;
338.         let storage_end: usize = base
339.             .checked_add(S::STORAGE_SIZE)
340.             .ok_or(BumpAllocError::Overflow)?;
341.         if end > storage_end {
342.             return Err(BumpAllocError::OutOfBounds);
343.         }
344.         if !ptr.is_multiple_of(A) {
345.             return Err(BumpAllocError::Misaligned);
346.         }
347. 
348.         // SAFETY: the backend contract guarantees valid stable storage; each slot index is handed
349.         // out at most once by atomic compare-and-swap.
350.         Ok(unsafe { &mut *(ptr as *mut [u8; N]) })
351.     }
352. 
353.     ///
354.     /// # Description
355.     ///
356.     /// Allocates the next fixed-size slot and reinterprets it as `MaybeUninit<T>`.
357.     ///
358.     /// # Returns
359.     ///
360.     /// On success, returns a mutable reference to an uninitialized `T`.
361.     ///
362.     /// # Errors
363.     ///
364.     /// - [`BumpAllocError::SizeMismatch`] if `size_of::<T>() != N`.
365.     /// - [`BumpAllocError::AlignmentMismatch`] if `align_of::<T>() > A`.
366.     /// - Any error from [`alloc()`](Self::alloc).
367.     ///
368.     /// # Safety
369.     ///
370.     /// The caller must initialise the returned `MaybeUninit<T>` before reading through it
371.     /// and ensure exclusive use of the returned reference.
372.     ///
373.     // SAFETY-SPEC: `external_body` for the same reason as `alloc` (it delegates to
374.     // `alloc` and then re-materializes the slot reference as `&'static mut
375.     // MaybeUninit<T>`). The size/alignment guard arms make the `T`-vs-`(N, A)`
376.     // contract caller-visible. Registered in `verus-ai-logs/tcb-allowed.md`.
377.     #[verus_verify(external_body)]
378.     #[verus_spec(result =>
379.         requires bump_view(self).inv(),
380.         ensures
381.             match result {
382.                 Ok(slot) => {
383.                     let v = bump_view(self);
384.                     let a = slot_ref_addr(slot);
385.                     &&& vstd::layout::size_of::<T>() == N as nat
386.                     &&& vstd::layout::align_of::<T>() <= A as nat
387.                     &&& a % (v.unit_align as int) == 0
388.                     &&& v.base <= a
389.                     &&& a + (N as int) <= v.base + (v.storage_size as int)
390.                 },
391.                 Err(e) => {
392.                     &&& e == BumpAllocError::SizeMismatch
393.                         || e == BumpAllocError::AlignmentMismatch
394.                         || e == BumpAllocError::Exhausted
395.                     &&& (e == BumpAllocError::SizeMismatch ==> vstd::layout::size_of::<T>()
396.                         != N as nat)
397.                     &&& (e == BumpAllocError::AlignmentMismatch ==> vstd::layout::align_of::<T>()
398.                         > A as nat)
399.                 },
400.             },
401.     )]
402.     pub unsafe fn alloc_as<T>(&self) -> Result<&'static mut MaybeUninit<T>, BumpAllocError> {
403.         if core::mem::size_of::<T>() != N {
404.             return Err(BumpAllocError::SizeMismatch);
405.         }
406.         if core::mem::align_of::<T>() > A {
407.             return Err(BumpAllocError::AlignmentMismatch);
408.         }
409. 
410.         let slot: &'static mut [u8; N] = self.alloc()?;
411.         // SAFETY: size/alignment checks above guarantee this cast is valid.
412.         Ok(unsafe { &mut *(slot.as_mut_ptr() as *mut MaybeUninit<T>) })
413.     }
414. }
415. 
416. impl<const N: usize, const A: usize, S: BssStorage> Default for FixedSizeBumpAllocator<N, A, S> {
417.     fn default() -> Self {
418.         // SAFETY: caller is responsible for the singleton invariant.
419.         unsafe { Self::new() }
420.     }
421. }
422. 
