427. #[cfg(test)]
428. mod tests {
429.     extern crate std;
430. 
431.     use super::{
432.         BssStorage,
433.         BumpAllocError,
434.         FixedSizeBumpAllocator,
435.     };
436.     use std::vec::Vec;
437. 
438.     #[repr(align(8))]
439.     struct StorageA {
440.         bytes: [u8; 16],
441.     }
442. 
443.     static mut STORAGE_A: StorageA = StorageA { bytes: [0; 16] };
444. 
445.     struct BackendA;
446. 
447.     unsafe impl BssStorage for BackendA {
448.         const NUM_UNITS: usize = 2;
449.         const STORAGE_SIZE: usize = 16;
450. 
451.         fn as_mut_ptr() -> *mut u8 {
452.             unsafe { core::ptr::addr_of_mut!(STORAGE_A.bytes) as *mut u8 }
453.         }
454.     }
455. 
456.     static ALLOC_A: FixedSizeBumpAllocator<8, 8, BackendA> =
457.         unsafe { FixedSizeBumpAllocator::new() };
458. 
459.     #[test]
460.     fn alloc_returns_distinct_slots() {
461.         let first: *mut u8 = ALLOC_A.alloc().expect("first alloc failed").as_mut_ptr();
462.         let second: *mut u8 = ALLOC_A.alloc().expect("second alloc failed").as_mut_ptr();
463.         assert_ne!(first, second);
464.     }
465. 
466.     #[repr(align(4))]
467.     struct StorageB {
468.         bytes: [u8; 8],
469.     }
470. 
471.     static mut STORAGE_B: StorageB = StorageB { bytes: [0; 8] };
472. 
473.     struct BackendB;
474. 
475.     unsafe impl BssStorage for BackendB {
476.         const NUM_UNITS: usize = 1;
477.         const STORAGE_SIZE: usize = 8;
478. 
479.         fn as_mut_ptr() -> *mut u8 {
480.             unsafe { core::ptr::addr_of_mut!(STORAGE_B.bytes) as *mut u8 }
481.         }
482.     }
483. 
484.     static ALLOC_B: FixedSizeBumpAllocator<8, 4, BackendB> =
485.         unsafe { FixedSizeBumpAllocator::new() };
486. 
487.     #[test]
488.     fn alloc_as_allows_typed_access() {
489.         let slot: &mut core::mem::MaybeUninit<[u32; 2]> =
490.             unsafe { ALLOC_B.alloc_as::<[u32; 2]>().expect("alloc_as failed") };
491.         slot.write([7, 11]);
492.         let typed: &mut [u32; 2] = unsafe { slot.assume_init_mut() };
493.         let values: Vec<u32> = Vec::from(*typed);
494.         assert_eq!(values, vec![7, 11]);
495.     }
496. 
497.     #[repr(align(8))]
498.     struct StorageC {
499.         bytes: [u8; 8],
500.     }
501. 
502.     static mut STORAGE_C: StorageC = StorageC { bytes: [0; 8] };
503. 
504.     struct BackendC;
505. 
506.     unsafe impl BssStorage for BackendC {
507.         const NUM_UNITS: usize = 1;
508.         const STORAGE_SIZE: usize = 8;
509. 
510.         fn as_mut_ptr() -> *mut u8 {
511.             unsafe { core::ptr::addr_of_mut!(STORAGE_C.bytes) as *mut u8 }
512.         }
513.     }
514. 
515.     static ALLOC_C: FixedSizeBumpAllocator<8, 8, BackendC> =
516.         unsafe { FixedSizeBumpAllocator::new() };
517. 
518.     #[test]
519.     fn alloc_returns_exhausted_error() {
520.         let _ = ALLOC_C.alloc().expect("first alloc failed");
521.         let result = ALLOC_C.alloc();
522.         assert_eq!(result.unwrap_err(), BumpAllocError::Exhausted);
523.     }
524. }
