19. /// `value / alignment` adjusted by one when the remainder is non-zero. Verus has
20. /// no specification for the `usize::div_ceil` intrinsic, so the equivalence is
21. /// proven here explicitly.
22. pub proof fn lemma_ceil_div(v: int, d: int, qd: int, r: int)
23.     requires
24.         d > 0,
25.         v >= 0,
26.         qd == v / d,
27.         r == v % d,
28.     ensures
29.         (if r == 0 {
30.             qd
31.         } else {
32.             qd + 1
33.         }) == (v + d - 1) / d,
34. {
35.     vstd::arithmetic::div_mod::lemma_fundamental_div_mod(v, d);
36.     assert(0 <= r < d);
37.     assert(v == d * qd + r);
38.     if r == 0 {
39.         assert((v + d - 1) / d == qd) by (nonlinear_arith)
40.             requires
41.                 d > 0,
42.                 v == d * qd,
43.                 0 <= 0 < d,
44.         ;
45.     } else {
46.         assert((v + d - 1) / d == qd + 1) by (nonlinear_arith)
47.             requires
48.                 d > 0,
49.                 v == d * qd + r,
50.                 0 < r < d,
